// Generated by scripts/gen-explainers.mjs from app/components/frame/frame.explainer.html. Do not edit.
const html = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\"\n      content=\"initial-scale=1, width=device-width\">\n<title>The frame</title>\n<style>\n  /* Two palettes, picked by the reader's system setting. */\n  :root {\n    color-scheme: light dark;\n    --page-bg: #fbfaf7;\n    --page-text: #1d1d1b;\n    --muted: #5b5b57;\n    --rule: #d9d6cf;\n    --diagram-line: #55534e;\n    --diagram-text: #1d1d1b;\n    --diagram-edge-text: #45433f;\n    --node-component-fill: #e8f0fb;\n    --node-component-stroke: #4a72b0;\n    --node-store-fill: #eaf5ec;\n    --node-store-stroke: #4a8a5a;\n    --node-external-fill: #f6eee2;\n    --node-external-stroke: #a27a3c;\n    --node-person-fill: #f3e9f5;\n    --node-person-stroke: #8a5a96;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --page-bg: #17181a;\n      --page-text: #e8e6e1;\n      --muted: #a9a6a0;\n      --rule: #3a3b3e;\n      --diagram-line: #b9b6af;\n      --diagram-text: #ecebe7;\n      --diagram-edge-text: #cfccc5;\n      --node-component-fill: #1d2a3d;\n      --node-component-stroke: #7fa3dc;\n      --node-store-fill: #1d3024;\n      --node-store-stroke: #79b98a;\n      --node-external-fill: #33291b;\n      --node-external-stroke: #d1a462;\n      --node-person-fill: #2e2233;\n      --node-person-stroke: #bb8cc7;\n    }\n  }\n  html, body {\n    margin: 0;\n    background: var(--page-bg);\n    color: var(--page-text);\n  }\n  body {\n    padding: 2rem 3rem;\n    font-size: 18px;\n    line-height: 1.6;\n    font-family: \"Source Serif 4\",\n      \"Iowan Old Style\", Georgia,\n      \"Times New Roman\", serif;\n  }\n  @media (max-width: 640px) {\n    body { padding: 1rem; font-size: 16px; }\n  }\n  h1, h2, h3, svg text {\n    font-family: \"Inter\", \"Segoe UI\",\n      system-ui, -apple-system,\n      Helvetica, Arial, sans-serif;\n  }\n  h1 {\n    font-size: 2rem;\n    margin: 0 0 1rem;\n  }\n  h2 {\n    font-size: 1.4rem;\n    margin: 2.5rem 0 0.75rem;\n    padding-bottom: 0.3rem;\n    border-bottom: 1px solid var(--rule);\n  }\n  p, li { margin: 0 0 1rem; }\n  code {\n    font-size: 0.9em;\n    font-family: \"JetBrains Mono\",\n      \"Cascadia Code\", Consolas,\n      \"Liberation Mono\", monospace;\n  }\n  table { width: 100%; border-collapse: collapse; margin: 0 0 1rem; }\n  th, td {\n    border: 1px solid var(--rule);\n    padding: 0.4rem 0.7rem;\n    text-align: left;\n    vertical-align: top;\n  }\n  .table-wrap { overflow-x: auto; }\n  #diagram {\n    display: block;\n    width: 100%;\n    height: auto;\n    margin: 1rem 0 2rem;\n  }\n</style>\n</head>\n<body>\n<h1>The frame</h1>\n<p>The frame is the layout every jarvis page of tom.Quest renders inside. A jarvis page is one of the pages that show the Jarvis agent system's own record: today that is <code>/tts</code>, the todo page, and later <code>/agents</code> and <code>/observe</code>. Every other page of the site keeps its own layout and the navigation bar across its top. This page explains what the frame shows, where each part sits, how it opens and closes, and why it is built this way. It describes the code in <code>app/components/frame/</code>, the directory this file sits in.</p>\n\n<h2>What the screen is made of</h2>\n<p>The screen is divided into a center, four drawers and four rails. The center is the area in the middle of the screen where the page shows its main content. A drawer is a panel that slides in from one edge of the screen and lies over the center until it is closed; there is one drawer for each edge, top, bottom, left and right. A rail is a thin strip along one edge of the screen that stays visible whether its drawer is open or closed; pressing a rail opens or closes its drawer, and the rail shows a few live numbers about what its drawer holds, so a closed drawer still reports its state. The picture below places each part where it sits on the screen. It draws the drawers beside the center so that every label can be read; on the real screen an open drawer lies over the edge of the center instead.</p>\n<svg id=\"diagram\"></svg>\n<p>The top rail is 40 pixels tall and spans the full width of the screen. It also holds the parts that belong to the site rather than to the page: the site's symbol in the top-left corner, which returns to the home page; the page's name followed by its (i) button; one line of the page's state with counts; a field to navigate to another page; and the account button in the top-right corner, which reads \"Log in\" for a visitor and shows the username once signed in. The space between the page's name and the navigate field is the top drawer's toggle. The bottom rail is 28 pixels tall and spans the full width. The left and right rails are 28 pixels wide and run between the top and bottom rails, with their labels turned on their side: the left one reads from bottom to top and the right one from top to bottom. The rails take 56 pixels of width and 68 pixels of height, so at a screen of 1440 by 900 pixels the center is 1384 by 832 pixels.</p>\n\n<h2>What each drawer holds</h2>\n<p>Each drawer has one role on every page, so the same edge means the same kind of content wherever it is opened. The roles run from the most general content to the most specific: the top chooses what the page covers, the left lists everything, the right shows one thing in full, and the bottom shows the raw rows underneath.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Part</th><th>What it holds</th><th>Default size and bounds</th><th>On /tts today</th></tr>\n  <tr><td>Center</td><td>The whole set the page is about, shown at once.</td><td>Everything inside the rails.</td><td>The todo page as it was before the frame: its calendar and everything tabs.</td></tr>\n  <tr><td>Top drawer</td><td>Scope: a time window, a calendar, filters; choosing one narrows what the center shows.</td><td>240 pixels tall, between 160 pixels and 45% of the screen height.</td><td>The calendar, as a placeholder for its later place here.</td></tr>\n  <tr><td>Left drawer</td><td>An index: the full lists, groups and search.</td><td>360 pixels wide, between 280 pixels and 40% of the screen width.</td><td>Empty, with its title.</td></tr>\n  <tr><td>Right drawer</td><td>One selected thing in full, with its actions and the definitions of its terms.</td><td>440 pixels wide, between 320 pixels and 50% of the screen width.</td><td>Empty, with its title.</td></tr>\n  <tr><td>Bottom drawer</td><td>The raw record: the event stream, a row's JSON, and the diagnostics.</td><td>320 pixels tall, between 200 pixels and 60% of the screen height.</td><td>The event stream, described below.</td></tr>\n</table>\n</div>\n<p>On <code>/tts</code> the bottom drawer holds the event stream. An event is one row of the <code>dtsEvents</code> table in the site's Convex database: a record, written at the moment something happened, of a todo being captured, a ruling being made or applied, a delegate answering, a session ending, a status changing, and every other kind the system records. The drawer reads the newest 200 rows through the query <code>api.tts.listRecentEvents</code>, newest first, and shows each one's time, its kind and the statement of the todo it concerns. Pressing a row shows the whole row as JSON beneath it, and pressing it again hides it. The rows update live: Convex pushes a new row to the page as soon as it is written. For the signed-in owner of the site the drawer also holds a diagnostics column: the current route, the signed-in role, the state of the connection to Convex, the screen size, the last captured console warnings and errors, and a button that copies all of it as text.</p>\n\n<h2>What a rail shows</h2>\n<p>A rail shows the drawer's title and up to three signals. A signal is one typed value the page computes from the same data its drawer shows, so the rail and the drawer cannot disagree. There are three kinds, and the page cannot put anything else in a rail.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Kind</th><th>What it shows</th><th>Example on /tts</th></tr>\n  <tr><td>count</td><td>A number in a monospaced font, coloured by the tone the page gives it.</td><td>The number of event rows loaded, for example 200.</td></tr>\n  <tr><td>dot</td><td>A small coloured circle for a state.</td><td>The dot in the bottom-right corner: green while Convex is connected and no console error was captured, yellow after an error, red when the connection is lost. Only the site owner's account sees it; pressing it opens the bottom drawer.</td></tr>\n  <tr><td>age</td><td>The time since a moment, in one short unit such as 40s, 12m, 3h or 5d, recomputed every ten seconds; it turns yellow once it passes a limit the page sets.</td><td>The age of the newest event, which turns yellow after six hours without one.</td></tr>\n</table>\n</div>\n<p>The tones are ok (green), warn (yellow), error (red), accent (orange) and faint (grey), the site's existing colours. When a drawer is closed and its signals differ from what they were at the moment it was last closed, its rail shows a short orange mark before the title, so a change is visible without opening the drawer. An open drawer's rail carries an orange line along its inner edge.</p>\n\n<h2>How the drawers overlap</h2>\n<p>A drawer always lies over the center and never pushes it aside: the center's size and position are fixed by the rails alone, so opening or closing a drawer moves nothing in the center by a single pixel. The top and bottom drawers span the space between the side rails, and the left and right drawers run the full height between the top and bottom rails. Where two open drawers meet, which one is on top is fixed by edge and not by which opened first: the right drawer lies over the left, the left over the bottom, and the bottom over the top. This order puts the most specific content over the more general, so the one thing shown in full on the right is never covered by a list or the record. Every rail lies over every drawer, so a rail can always be pressed. The layers are the <code>--z-*</code> values at the top of <code>app/globals.css</code>, the one list every stacked surface of the site takes its layer from.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Layer</th><th>Value</th></tr>\n  <tr><td>center</td><td>0</td></tr>\n  <tr><td>menus</td><td>10</td></tr>\n  <tr><td>top, bottom, left, right drawers</td><td>20, 21, 22, 23</td></tr>\n  <tr><td>rails</td><td>30</td></tr>\n  <tr><td>the navigation menu</td><td>40</td></tr>\n  <tr><td>dialogs</td><td>50</td></tr>\n  <tr><td>an explainer opened by an (i)</td><td>60</td></tr>\n  <tr><td>toasts</td><td>70</td></tr>\n</table>\n</div>\n<p>When the left and right drawers are both open and together would leave the center narrower than 160 pixels, opening one closes the other. On a screen narrower than 1024 pixels only one side drawer is open at a time. There is no darkened layer behind a drawer on a desktop screen, and a drawer never closes by itself: it stays open until its rail, its × button or the Escape key closes it.</p>\n\n<h2>Keys and pointer</h2>\n<p>The keys work whenever the keyboard is not typing into a text field and no dialog is open.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Key</th><th>Effect</th></tr>\n  <tr><td>W, A, S, D</td><td>Open or close the top, left, bottom and right drawer.</td></tr>\n  <tr><td>Shift with W, A, S or D</td><td>Open that drawer and move keyboard focus into it.</td></tr>\n  <tr><td>/</td><td>Move keyboard focus to the navigate field in the top rail.</td></tr>\n  <tr><td>Escape</td><td>Close the topmost thing: an open explainer first, then a dialog, then the open drawers one at a time in the order right, left, bottom, top.</td></tr>\n</table>\n</div>\n<p>With a pointer, pressing a rail opens or closes its drawer, and a drawer's header holds its title and a × button that closes it. Which drawers are open is remembered per page and per edge in the browser's local storage, through a Zustand store (<code>frame-store.ts</code>), so a page reopens as it was left. It is never written into the page's address.</p>\n\n<h2>On a phone</h2>\n<p>On a screen narrower than 640 pixels the side rails are removed and the center takes the full width. The top rail grows to 44 pixels and holds the symbol, the page's name, the top drawer's toggle and the account button. The bottom rail grows to 48 pixels and is split into three cells, which open the left, bottom and right drawers. Drawers open one at a time as sheets over a darkened layer that closes them when pressed; the side drawers take 88% of the screen width. Opening a drawer by swiping from a screen edge is left out on purpose, because phones already use those edges: a swipe from the left or right edge goes back in the browser's history on iOS and is the system back gesture on Android, the bottom edge opens the home screen, and the top edge opens the notifications.</p>\n\n<h2>The (i) button and explainers</h2>\n<p>An (i) button sits right after the name of the thing it explains, one per component and never one per control. Pressing it opens that component's explainer across the whole screen, with a header strip holding the explainer's title and a × button; the × or the Escape key closes it. An explainer is one self-contained HTML file committed beside the code it describes and named <code>&lt;name&gt;.explainer.html</code>; this page is <code>frame.explainer.html</code>, and it opens from the (i) after the page's name.</p>\n<p>The explainer is shown in an iframe, an embedded browser page, with two protections. The iframe is sandboxed with scripts allowed but without its own origin, so the script that draws its diagram runs as a page from nowhere: it cannot read the site's storage, cookies or page, and it cannot navigate the site, submit a form or open a window. And the viewer inserts a Content-Security-Policy tag at the start of the explainer's head that refuses every network request, so an explainer that tried to load anything would fail instead. An explainer carries a light and a dark palette and chooses between them by the reader's system setting, and inside an iframe that setting is the operating system's, not the site's. The site is always dark, so before showing the file the viewer rewrites its palette choice so that the dark palette always applies; the same file opened from disk still follows the system setting.</p>\n<p>The <code>explainer</code> argument of the (i) is typed: <code>scripts/gen-explainers.mjs</code> finds every <code>*.explainer.html</code> under <code>app/</code> and writes <code>explainer-registry.generated.ts</code>, whose type <code>ExplainerId</code> lists exactly the names that have a file, so naming an explainer that does not exist fails the type check. Each file becomes its own module that is loaded only when its (i) is pressed, so no page downloads explainers it does not open. <code>explainers.test.ts</code> fails when the committed registry differs from what the script would write.</p>\n\n<h2>What the frame changes and what it leaves alone</h2>\n<p>A page is marked as a frame page by <code>frame: true</code> on its row in <code>app/components/page-routes.ts</code>. For such a page, <code>app/components/app-shell.tsx</code> renders no navigation bar and no top padding, and the page renders <code>&lt;Frame&gt;</code> itself, passing its name, its center and, for each drawer, a title, its rail signals and its content. The page passes content only: the frame owns every position, layer and size. The diagnostics panel that on other pages slides in from the left and pushes the page to the right is not drawn on a frame page, because pushing the center is what the frame rules out; its contents are the diagnostics column of the bottom drawer instead. Every page not marked <code>frame: true</code> is unchanged: it keeps the navigation bar, its own layout and the side diagnostics panel. Inside the frame all text is set in IBM Plex Sans, with IBM Plex Mono for numbers, identifiers and code; the site's display face is not used there.</p>\n\n<script>\n// The diagram is two lists; change them and reload, nothing else.\n// A node: id, label (lines; the first is its name), x, y, w, h in\n// diagram units, and kind: component, store, external or person.\n// An edge: from and to (node ids) and a label (\"\" for none).\nconst NODES = [\n  { id: \"top-rail\", x: 20, y: 20, w: 900, h: 56, kind: \"external\",\n    label: [\"Top rail, 40 px\",\n      \"logo · page name (i) · state · top drawer toggle · navigate · account\"] },\n  { id: \"left-rail\", x: 20, y: 88, w: 70, h: 384, kind: \"external\",\n    label: [\"Left\", \"rail\", \"28 px\"] },\n  { id: \"right-rail\", x: 850, y: 88, w: 70, h: 384, kind: \"external\",\n    label: [\"Right\", \"rail\", \"28 px\"] },\n  { id: \"bottom-rail\", x: 20, y: 484, w: 900, h: 56, kind: \"external\",\n    label: [\"Bottom rail, 28 px\",\n      \"event stream signals · diagnostics dot in the corner\"] },\n  { id: \"top-drawer\", x: 102, y: 88, w: 736, h: 64, kind: \"component\",\n    label: [\"Top drawer\", \"scope: calendar, window, filters\"] },\n  { id: \"left-drawer\", x: 102, y: 164, w: 200, h: 308, kind: \"component\",\n    label: [\"Left drawer\", \"index: full lists\"] },\n  { id: \"right-drawer\", x: 638, y: 164, w: 200, h: 308, kind: \"component\",\n    label: [\"Right drawer\", \"one thing in full\"] },\n  { id: \"center\", x: 314, y: 164, w: 312, h: 196, kind: \"store\",\n    label: [\"Center\", \"the whole set at once\"] },\n  { id: \"bottom-drawer\", x: 314, y: 372, w: 312, h: 100, kind: \"component\",\n    label: [\"Bottom drawer\", \"raw record: events, JSON\"] },\n];\nconst EDGES = [];\n\n(() => {\n  const SVG_NS = \"http://www.w3.org/2000/svg\";\n  const svg = document.querySelector(\"#diagram\");\n  const R = 8;          // corner radius of a box\n  const HEAD = 11;      // arrowhead length\n  const HALF = 5.5;     // arrowhead half width\n  const STEP = 18;      // label line height\n  const byId = new Map(NODES.map((n) => [n.id, n]));\n  const W = Math.max(...NODES.map((n) => n.x + n.w)) + 20;\n  const H = Math.max(...NODES.map((n) => n.y + n.h)) + 20;\n  svg.setAttribute(\"viewBox\", \"0 0 \" + W + \" \" + H);\n  svg.setAttribute(\"role\", \"img\");\n  svg.style.maxWidth = W + \"px\"; // shrink to fit, never grow past 1:1\n\n  const el = (tag, attrs, style = {}) => {\n    const e = document.createElementNS(SVG_NS, tag);\n    Object.entries(attrs).forEach(([k, v]) => e.setAttribute(k, v));\n    Object.assign(e.style, style);\n    svg.appendChild(e);\n    return e;\n  };\n  const mid = (n) => [n.x + 0.5 * n.w, n.y + 0.5 * n.h];\n\n  // Where the ray from n's middle toward (tx, ty) leaves its rounded box.\n  const border = (n, tx, ty) => {\n    const [cx, cy] = mid(n);\n    const dx = tx - cx, dy = ty - cy;\n    const hw = n.w / 2, hh = n.h / 2;\n    // Dividing by a zero delta gives Infinity, so no special case is needed.\n    const k = Math.min(hw / Math.abs(dx),\n      hh / Math.abs(dy));\n    const px = cx + dx * k, py = cy + dy * k;\n    const onSide = Math.abs(px - cx) <= hw - R || Math.abs(py - cy) <= hh - R;\n    if (onSide) return [px, py];\n    // In a corner: meet the corner's circle instead of the square corner.\n    const qx = cx - (cx + Math.sign(dx) * (hw - R));\n    const qy = cy - (cy + Math.sign(dy) * (hh - R));\n    const a = dx * dx + dy * dy;\n    const b = 2 * (qx * dx + qy * dy);\n    const c = qx * qx + qy * qy - R * R;\n    const root = Math.sqrt(b * b - 4 * a * c);\n    const s = (root - b) / (2 * a);\n    return [cx + dx * s, cy + dy * s];\n  };\n\n  // Arrows before boxes, so no arrow crosses a box's text.\n  for (const { from, to, label } of EDGES) {\n    const f = byId.get(from), t = byId.get(to);\n    const [x1, y1] = border(f, ...mid(t));\n    const [x2, y2] = border(t, ...mid(f));\n    const ang = Math.atan2(y2 - y1, x2 - x1);\n    const ux = Math.cos(ang), uy = Math.sin(ang);\n    const bx = x2 - HEAD * ux, by = y2 - HEAD * uy;\n    const LINE = \"var(--diagram-line)\";\n    el(\"line\", { x1, y1, x2: bx, y2: by },\n      { stroke: LINE, strokeWidth: \"1.6\" });\n    const tip = [[x2, y2], [bx + HALF * uy, by - HALF * ux],\n      [bx - HALF * uy, by + HALF * ux]];\n    el(\"polygon\", { points: tip.map((p) => p.join(\",\")).join(\" \") },\n      { fill: LINE });\n    if (!label) continue;\n    // The label sits beside the line on its upper side, growing away from it.\n    let nx = -uy, ny = ux;\n    const flip = ny > 0 || (ny === 0 && nx > 0);\n    if (flip) { nx *= -1; ny *= -1; }\n    let anchor = \"start\";\n    if (Math.abs(nx) < 0.3) anchor = \"middle\";\n    else if (nx < 0) anchor = \"end\";\n    el(\"text\", {\n      x: (x1 + x2) / 2 + nx * 10,\n      y: (y1 + y2) / 2 + ny * 10,\n      \"text-anchor\": anchor,\n      \"dominant-baseline\":\n        ny < -0.9 ? \"auto\" : \"middle\",\n    }, {\n      fill: \"var(--diagram-edge-text)\",\n      fontSize: \"13px\",\n      paintOrder: \"stroke\",\n      stroke: \"var(--page-bg)\",\n      strokeWidth: \"5px\",\n      strokeLinejoin: \"round\",\n    }).textContent = label;\n  }\n\n  // Boxes, then their labels: the name larger and bold, the rest plain.\n  for (const n of NODES) {\n    const box = { width: n.w, height: n.h, x: n.x, y: n.y };\n    el(\"rect\", { ...box, rx: R, ry: R }, {\n      fill: \"var(--node-\" + n.kind + \"-fill)\",\n      stroke: \"var(--node-\" + n.kind + \"-stroke)\",\n      strokeWidth: \"1.4\",\n    });\n    const [cx, cy] = mid(n);\n    const first = cy - ((n.label.length - 1) * STEP) / 2;\n    n.label.forEach((text, i) => {\n      el(\"text\", {\n        x: cx, y: first + i * STEP,\n        \"text-anchor\": \"middle\",\n        \"dominant-baseline\": \"middle\",\n      }, {\n        fill: \"var(--diagram-text)\",\n        fontSize: i === 0 ? \"15px\" : \"13px\",\n        fontWeight: i === 0 ? \"600\" : \"400\",\n      }).textContent = text;\n    });\n  }\n})();\n</script>\n</body>\n</html>\n";
export default html;
